    public static partial class BossProfiles
    {
        public const string PolarisSetId = "set.boss_polaris";
        public const string PolarisNativeContract = "Mon_Special_BossPolaris;GoldenSpear-first-hit-armor-Purgatory-CounterSpell-RainFire-JumpStomp;authored-values-not-serialized;no-guessed-Beam-CursedDive;native-main-confirmed-memory-forward-verified-displacement-departure-landing-hostile-native-damage;generated-excluded;source-owned-shields;no-boss-instance-no-reward-no-link-no-summon-no-immunity-no-skill-theft;four-fields-eight-targets;epoch-teardown";
        public const string PolarisEventOrder = "observe-own-stage-guard-end;admit-native-input;counter-reply;parts-independent;mode-gate500ms;holy-beast-seal;cycle-first-e2-fixed8s-no-duplicate-refresh;finisher-replaces-stage-guard;light45-actual-terminal-neutral45-after500ms";
        private static BossMoveProfile PolarisProfile(string id, string ja, string en, BossChannelDef[] channels, params BossAction[] actions)
            => new BossMoveProfile("boss_polaris." + id, PolarisSetId, new Txt(ja, en), channels, actions);
        private static BossAction PolarisSpear(BossEvent e, string channel, int cd = 0, int count = 1)
            => new BossAction(e, BossMechanism.Projectile, BossPayload.Damage, channel, cooldownMillis: cd,lifetimeMillis:BossPolarisBalance.SpearLifetimeMillis, count: count,maxTargets:BossPolarisBalance.SpearMaxTargets,maxInstances:BossPolarisBalance.SpearMaxInstances,rangeMilli:BossPolarisBalance.SpearRangeMilli,widthMilli:BossPolarisBalance.SpearWidthMilli,speedMilli:BossPolarisBalance.SpearSpeedMilli,angleMilli:count == 2 ? BossPolarisBalance.SpearDoubleAngleMilli : 0, firstHitOnly: true, element: BossElement.Light);
        private static BossAction PolarisGuard(BossEvent e, string channel, int cd, int life)
            => new BossAction(e, BossMechanism.Defense, BossPayload.Shield, channel, cooldownMillis: cd,
                lifetimeMillis: life,maxTargets:BossPolarisBalance.GuardMaxTargets,maxInstances:BossPolarisBalance.GuardMaxInstances, followOwner: true);
        private static BossAction PolarisCircle(BossEvent e, string channel, int cd, int radius, int delay, BossElement element = BossElement.Neutral)
            => new BossAction(e, BossMechanism.Field, BossPayload.Damage, channel, cooldownMillis: cd,
                delayMillis: delay,maxTargets:BossPolarisBalance.CircleMaxTargets,maxInstances:BossPolarisBalance.CircleMaxInstances, radiusMilli: radius,rangeMilli:BossPolarisBalance.CircleRangeMilli, element: element);
        internal static BossMoveProfile[] CreatePolarisMoves() => new[]
        {
            PolarisProfile("weapon", "通常攻撃が敵に命中したとき、正面の左右6°の方向に光の槍を2本放つ。槍の射程は8m、弾速は12m/秒、幅は0.4m、持続は0.8秒で、それぞれ攻撃力・魔力の高い方の24%の光属性ダメージを与える。同じ敵に命中するのは1本だけである。再発動まで5秒かかる。", "When your basic attack hits an enemy, fire 2 spears of light, angled 6° left and right of straight ahead. Each has an 8m range, a speed of 12m per second, a width of 0.4m, and a 0.8-second lifetime, and deals Light damage equal to 24% of whichever is higher: your Attack or Ability Power. Only 1 spear can hit each enemy. Cooldown: 5 seconds.",
                new[] { C("PolarisGoldenSpear",BossPolarisBalance.PolarisGoldenSpearValue,BossPolarisBalance.PolarisGoldenSpearCap) }, PolarisSpear(BossEvent.MainHit,"PolarisGoldenSpear",BossPolarisBalance.WeaponA0CooldownMillis,BossPolarisBalance.WeaponA0Count)),
            PolarisProfile("armor", "敵の攻撃でダメージを受けた後、最大HPの16%の障壁を得る。障壁は4秒かけて徐々に減っていく。再発動まで12秒かかる。", "After taking damage from an enemy attack, gain a shield equal to 16% of your maximum HP that gradually decays over 4 seconds. Cooldown: 12 seconds.",
                new[] { C("PolarisFirstGuard",BossPolarisBalance.PolarisFirstGuardValue,BossPolarisBalance.PolarisFirstGuardCap,BossCoefficientKind.Shield) }, PolarisGuard(BossEvent.NativeDamageTaken,"PolarisFirstGuard",BossPolarisBalance.ArmorA0CooldownMillis,BossPolarisBalance.ArmorA0LifetimeMillis)),
            PolarisProfile("charm", "記憶を使ったとき、指定位置（自身から6m以内）に半径2mの炎の領域を展開する。0.4秒の予告の後、0秒後、0.5秒後、1秒後に、それぞれ攻撃力・魔力の高い方の12%の火属性ダメージを与え、同じ敵には最大で合計36%となる。敵に初めて命中したときは、最大HPの6%を自身が回復する。回復は1回だけで、再発動まで9秒かかる。", "When you use a memory, create a fire field with a 2m radius at the selected location within 6m of you. After a 0.4-second warning, it deals Fire damage at 0, 0.5, and 1 second, each time equal to 12% of whichever is higher: your Attack or Ability Power (up to 36% total per enemy). Its first hit on an enemy heals you for 6% of your maximum HP, once only. Cooldown: 9 seconds.",
                new[] { C("PolarisPurgatory",BossPolarisBalance.PolarisPurgatoryValue,BossPolarisBalance.PolarisPurgatoryCap), C("PolarisPurgatoryReturn",BossPolarisBalance.PolarisPurgatoryReturnValue,BossPolarisBalance.PolarisPurgatoryReturnCap,BossCoefficientKind.Heal) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.Field,BossPayload.Damage,"PolarisPurgatory",anchor:BossAnchor.Cursor,cooldownMillis:BossPolarisBalance.CharmA0CooldownMillis,delayMillis:BossPolarisBalance.CharmA0DelayMillis,intervalMillis:BossPolarisBalance.CharmA0IntervalMillis,count:BossPolarisBalance.CharmA0Count,maxTargets:BossPolarisBalance.CharmA0MaxTargets,maxInstances:BossPolarisBalance.CharmA0MaxInstances,radiusMilli:BossPolarisBalance.CharmA0RadiusMilli,rangeMilli:BossPolarisBalance.CharmA0RangeMilli,element:BossElement.Fire),
                new BossAction(BossEvent.Clock,BossMechanism.Defense,BossPayload.Heal,"PolarisPurgatoryReturn",maxTargets:BossPolarisBalance.CharmA1MaxTargets,maxInstances:BossPolarisBalance.CharmA1MaxInstances)),
            PolarisProfile("head", "記憶を使ったとき、最大HPの8%の障壁を1秒間得て、1秒間の反撃態勢に入る。この間に敵の攻撃で初めてダメージを受けたとき、8m以内の攻撃者へ光弾を1発放ち、攻撃力・魔力の高い方の28%の光属性ダメージを与える。光弾の射程は8m、弾速は12m/秒、幅は0.4m、持続は0.8秒。再発動まで10秒かかり、スタンはしない。", "When you use a memory, gain a shield equal to 8% of your maximum HP for 1 second and enter a counter stance for 1 second. The first time you take damage from an enemy attack during this stance, fire 1 light projectile at the attacker if they are within 8m. It has an 8m range, a speed of 12m per second, a width of 0.4m, and a 0.8-second lifetime, and deals Light damage equal to 28% of whichever is higher: your Attack or Ability Power. Cooldown: 10 seconds. Does not stun.",
                new[] { C("PolarisCounterGuard",BossPolarisBalance.PolarisCounterGuardValue,BossPolarisBalance.PolarisCounterGuardCap,BossCoefficientKind.Shield), C("PolarisCountershot",BossPolarisBalance.PolarisCountershotValue,BossPolarisBalance.PolarisCountershotCap) },
                PolarisGuard(BossEvent.MemoryUse,"PolarisCounterGuard",BossPolarisBalance.HeadA0CooldownMillis,BossPolarisBalance.HeadA0LifetimeMillis), PolarisSpear(BossEvent.NativeDamageTaken,"PolarisCountershot")),
            PolarisProfile("hands", "通常攻撃が敵に命中したとき、命中地点（自身から6m以内）の周囲半径1.5m、角度0°、120°、240°の位置に、半径1.2mの火炎円を3個配置する。0.4秒の予告の後、0秒後、0.15秒後、0.3秒後に、それぞれ攻撃力・魔力の高い方の12%の火属性ダメージを与え、同じ敵には最大で合計36%となる。再発動まで8秒かかる。", "When your basic attack hits an enemy, place 3 fire circles, each with a 1.2m radius, around the hit location within 6m of you. The circles are 1.5m from that location at angles of 0°, 120°, and 240°. After a 0.4-second warning, they strike at 0, 0.15, and 0.3 seconds, each dealing Fire damage equal to 12% of whichever is higher: your Attack or Ability Power (up to 36% total per enemy). Cooldown: 8 seconds.",
                new[] { C("PolarisRainfire",BossPolarisBalance.PolarisRainfireValue,BossPolarisBalance.PolarisRainfireCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.Field,BossPayload.Damage,"PolarisRainfire",anchor:BossAnchor.Hit,cooldownMillis:BossPolarisBalance.HandsA0CooldownMillis,delayMillis:BossPolarisBalance.HandsA0DelayMillis,intervalMillis:BossPolarisBalance.HandsA0IntervalMillis,count:BossPolarisBalance.HandsA0Count,maxTargets:BossPolarisBalance.HandsA0MaxTargets,maxInstances:BossPolarisBalance.HandsA0MaxInstances,radiusMilli:BossPolarisBalance.HandsA0RadiusMilli,rangeMilli:BossPolarisBalance.HandsA0RangeMilli,magnitudeMilli:BossPolarisBalance.HandsA0MagnitudeMilli,element:BossElement.Fire)),
            PolarisProfile("feet", "移動が終わったとき、その着地点に予告を出し、0.25秒後に半径2.5mの範囲へ攻撃力・魔力の高い方の36%の無属性の踏みつけダメージを1回与える。再発動まで7秒かかり、追加の移動やスタンはない。", "When you finish moving, after a 0.25-second warning, stomp once at your landing position within a 2.5m radius, dealing Neutral damage equal to 36% of whichever is higher: your Attack or Ability Power. Cooldown: 7 seconds. Does not cause additional movement or stun.",
                new[] { C("PolarisStarstomp",BossPolarisBalance.PolarisStarstompValue,BossPolarisBalance.PolarisStarstompCap) }, PolarisCircle(BossEvent.MovementCompleted,"PolarisStarstomp",BossPolarisBalance.FeetA0CooldownMillis,BossPolarisBalance.FeetA0RadiusMilli,BossPolarisBalance.FeetA0DelayMillis)),
            // stage2 の Actions[0] の CooldownMillis（Stage2A0CooldownMillis＝500）は、HostAuthority.BossPolaris の
            // PolarisPhase が入力間隔ゲート（仕様0.5秒）の鍵と待ち時間として流用する。変えるときは実行側と両方確認する。
            PolarisProfile("stage2", "初期状態は「神聖（Holy）」。記憶を使うと神聖モードを選択し、最大HPの12%の障壁を3秒間得る。障壁の再発動まで8秒かかる。移動を終えると「魔獣（Beast）」モードを選択し、着地点の半径2.5mに攻撃力・魔力の高い方の36%の踏みつけダメージを与える。攻撃の再発動まで4秒かかる。入力間隔は0.5秒。それぞれの再発動待ちの間もモードの切り替えはできるが、技の予約はできない。", "Start in Holy mode. Using a memory selects Holy mode and grants a shield equal to 12% of your maximum HP for 3 seconds. Shield Cooldown: 8 seconds. Finishing movement selects Beast mode and stomps within a 2.5m radius of your landing position for damage equal to 36% of the higher of your Attack and Ability Power. Attack Cooldown: 4 seconds. Actions that select a mode must be at least 0.5 seconds apart. You can still switch modes during either Cooldown, but cannot queue a technique for later.",
                new[] { C("PolarisHolyGuard",BossPolarisBalance.PolarisHolyGuardValue,BossPolarisBalance.PolarisHolyGuardCap,BossCoefficientKind.Shield), C("PolarisBeastStomp",BossPolarisBalance.PolarisBeastStompValue,BossPolarisBalance.PolarisBeastStompCap) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.Ledger,BossPayload.Mode,cooldownMillis:BossPolarisBalance.Stage2A0CooldownMillis,count:BossPolarisBalance.Stage2A0Count,maxTargets:BossPolarisBalance.Stage2A0MaxTargets,maxInstances:BossPolarisBalance.Stage2A0MaxInstances),
                PolarisGuard(BossEvent.MemoryUse,"PolarisHolyGuard",BossPolarisBalance.Stage2A1CooldownMillis,BossPolarisBalance.Stage2A1LifetimeMillis), PolarisCircle(BossEvent.MovementCompleted,"PolarisBeastStomp",BossPolarisBalance.Stage2A2CooldownMillis,BossPolarisBalance.Stage2A2RadiusMilli,BossPolarisBalance.Stage2A2DelayMillis)),
            PolarisProfile("stage3", "神聖から魔獣へ移行したとき、出発点に紋印を1個生成する。移行は、移動の完了、または神聖の障壁が全て消費されたときや効果が終わったときに起こり、障壁が終わったときの出発点は現在地になる。紋印は4秒間持続する。次に発動する魔獣モード中の通常攻撃命中または移動完了による踏みつけは、6m以内にある印を消費し、発生地点をその印の位置に移して、0.35秒の予告で発動する。同じモードの間は新しい印は生成されず、二重にヒットすることもない。記憶を使って神聖に戻ると、古い印は破棄される。", "Switching from Holy to Beast mode by finishing movement, fully using up Holy's shield, or letting it expire creates 1 seal lasting 4 seconds at your departure point, or at your current position when the shield ends. Your next Beast-mode stomp triggered by a basic attack hit or completed movement consumes a seal within 6m and strikes from that seal after a 0.35-second warning instead. Staying in the same mode creates no new seals, and the stomp does not hit twice. Using a memory to return to Holy mode discards the old seal.",
                new[] { C("PolarisDepartureReach",BossPolarisBalance.PolarisDepartureReachValue,BossPolarisBalance.PolarisDepartureReachCap,BossCoefficientKind.Distance) },
                new BossAction(BossEvent.MovementCompleted,BossMechanism.Ledger,BossPayload.Mark,delayMillis:BossPolarisBalance.Stage3A0DelayMillis,lifetimeMillis:BossPolarisBalance.Stage3A0LifetimeMillis,maxTargets:BossPolarisBalance.Stage3A0MaxTargets,maxInstances:BossPolarisBalance.Stage3A0MaxInstances,rangeMilli:BossPolarisBalance.Stage3A0RangeMilli)),
            // stage6 の Actions[0] の CooldownMillis（Stage6A0CooldownMillis＝18000）は、6部位技の再使用制限
            // （仕様18秒）として HostAuthority.BossPolaris の PolarisFinish が使う。意図しない短縮・延長を防ぐため、
            // ここを変えるときは仕様文と合わせて確認する。
            PolarisProfile("stage6", "最初に記憶を使ってから8秒以内に「神聖→魔獣→神聖」と移行を完了すると発動する。再発動まで18秒かかり、重複した入力で進行したり時間が延びたりはしない。再発動待ちの間に成立した場合は保持されず、破棄される。このとき、最後の記憶使用時の障壁（12%）は、次の効果に置き換わる。自身から6m以内の印（なければ自身）から、向きを固定した光槍を放ち、攻撃力・魔力の高い方の90%の光属性ダメージを与える。光槍の射程は8m、弾速は12m/秒、幅は0.4mで、最初の敵、壁、射程の終端で止まる。その実際の終点に予告を出し、0.5秒後に半径3mの範囲へ攻撃力・魔力の高い方の90%の無属性の踏みつけダメージを与える。同じ敵には最大で合計180%（上限200%）まで与える。さらに最大HPの76%（上限80%）の障壁を得て、障壁は6秒かけて線形に減っていく。", "Complete Holy → Beast → Holy within 8 seconds of your first memory use to activate this effect. Cooldown: 18 seconds. Repeating the same action does not advance the sequence or extend its time limit. A sequence completed during the Cooldown is discarded, not saved. Replace the final memory use's 12% shield with the following: fire a spear of light in a fixed direction from a seal within 6m of you, or from you if there is none. It deals Light damage equal to 90% of the higher of your Attack and Ability Power, has an 8m range, a speed of 12m per second, and a width of 0.4m, and stops at the first enemy, wall, or end of its range. After a 0.5-second warning at its actual stopping point, stomp within a 3m radius for Neutral damage equal to 90% of the higher of your Attack and Ability Power (up to 180% total per enemy, with damage capped at 200%). Gain a shield equal to 76% of your maximum HP (capped at 80%) that decays at a constant rate over 6 seconds.",
                new[] { C("PolarisDualSanctity",BossPolarisBalance.PolarisDualSanctityValue,BossPolarisBalance.PolarisDualSanctityCap), C("PolarisReturnGuard",BossPolarisBalance.PolarisReturnGuardValue,BossPolarisBalance.PolarisReturnGuardCap,BossCoefficientKind.Shield) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.Ledger,BossPayload.Mark,cooldownMillis:BossPolarisBalance.Stage6A0CooldownMillis,lifetimeMillis:BossPolarisBalance.Stage6A0LifetimeMillis,count:BossPolarisBalance.Stage6A0Count,maxTargets:BossPolarisBalance.Stage6A0MaxTargets,maxInstances:BossPolarisBalance.Stage6A0MaxInstances),
                PolarisSpear(BossEvent.MemoryUse,"PolarisDualSanctity"), PolarisCircle(BossEvent.Clock,"PolarisDualSanctity",BossPolarisBalance.Stage6A2CooldownMillis,BossPolarisBalance.Stage6A2RadiusMilli,BossPolarisBalance.Stage6A2DelayMillis),
                PolarisGuard(BossEvent.MemoryUse,"PolarisReturnGuard",BossPolarisBalance.Stage6A3CooldownMillis,BossPolarisBalance.Stage6A3LifetimeMillis)),
        };
